globalThis.KENGURU_CHOICE_LAYOUTS = {"2013-3-4/7":{"options":[{"image":"assets/separated-choices/2013-3-4/07-1.webp","pixelWidth":127,"pixelHeight":107},{"image":"assets/separated-choices/2013-3-4/07-2.webp","pixelWidth":114,"pixelHeight":124},{"image":"assets/separated-choices/2013-3-4/07-3.webp","pixelWidth":101,"pixelHeight":141},{"image":"assets/separated-choices/2013-3-4/07-4.webp","pixelWidth":96,"pixelHeight":139},{"image":"assets/separated-choices/2013-3-4/07-5.webp","pixelWidth":128,"pixelHeight":98}],"condition":{"src":"assets/separated-choices/2013-3-4/07-condition.webp","width":173,"height":204}},"2013-3-4/18":{"options":[{"image":"assets/separated-choices/2013-3-4/18-1.webp","pixelWidth":142,"pixelHeight":43},{"image":"assets/separated-choices/2013-3-4/18-2.webp","pixelWidth":77,"pixelHeight":43},{"image":"assets/separated-choices/2013-3-4/18-3.webp","pixelWidth":110,"pixelHeight":75},{"image":"assets/separated-choices/2013-3-4/18-4.webp","pixelWidth":77,"pixelHeight":75},{"text":"Такие две фигуры сложить невозможно"}],"condition":{"src":"assets/separated-choices/2013-3-4/18-condition.webp","width":345,"height":144}}};
globalThis.KENGURU_LEGACY = [[2013,"3–4 классы",[[834,103,"Какую из букв слова КЕНГА можно написать, не отрывая карандаша от бумаги и не проходя по одной линии дважды?",{},"D","Буква одним росчерком",[["Найди угол","У буквы Г два отрезка, и они соединены в одном углу."],["Проведи линию","Начни со свободного конца одного отрезка, пройди через угол и закончи на другом конце."]],""],[834,103,"В равенстве 4 ● + 5 ● = 104 символом ● заменена одна и та же цифра. Какая?",{"0":[51.8,69.1,31.6,26.5],"1":[178.1,69.1,31.6,26.5],"2":[294.9,69.1,31.6,26.5],"3":[411.6,69.1,28.8,26.5],"4":[528.4,69.1,31.6,26.5]},"E","Одинаковые цифры",[["Отдели десятки","Числа начинаются с 4 и с 5, поэтому их десятки дают 40 + 50 = 90."],["Найди единицы","До 104 не хватает 14. Две одинаковые цифры дают 14, значит, каждая равна 7."]],""],[834,177,"",{},"C","Поиск квадрата",[["Рассмотри рисунок","Круги видны на мордочке, треугольники — у ушей и лап, а шестиугольник образует контур головы."],["Сравни прямоугольники","Прямоугольные детали вытянуты в высоту. Фигуры с четырьмя равными сторонами и прямыми углами здесь нет."]],""],[834,103,"Миша измерил длины пяти палочек и записал результаты этих измерений. Какой из результатов А–Д самый большой?",{"0":[51.8,68.5,31.6,26.5],"1":[228.3,68.5,31.6,26.5],"2":[411.6,68.5,31.6,26.5],"3":[561.7,68.5,28.8,26.5],"4":[677.8,68.5,31.6,26.5]},"A","Длины палочек",[["Переведи в миллиметры","В дециметре 100 мм, а в сантиметре 10 мм. Поэтому 3 дм 2 см — это 320 мм."],["Сравни","Другие длины равны 37, 35, 30 и 302 мм. Больше всего 320 мм."]],""],[834,238,"Пятеро мальчиков обсуждали свойства числа 325. Андрей: «Это трехзначное число». Боря: «Все цифры этого числа различны». Витя: «Сумма его цифр равна 10». Гриша: «Цифра единиц равна 5». Даня: «Все его цифры нечетны». Кто из мальчиков ошибся?",{"0":[51.8,203.9,31.6,26.5],"1":[201.8,203.9,31.6,26.5],"2":[351.8,203.9,31.6,26.5],"3":[501.3,203.9,28.8,26.5],"4":[651.3,203.9,31.6,26.5]},"E","Цифры числа 325",[["Проверь число","Цифры 3, 2 и 5 различны, их сумма равна 10, а последняя цифра — 5."],["Проверь чётность","Цифра 2 чётная. Значит, ошибся Даня."]],""],[834,102,"У Пети было 36 конфет. Он раздал все конфеты гостям поровну. Сколько гостей у него могло быть?",{"0":[51.8,68.5,31.6,26.5],"1":[201.8,68.5,31.6,26.5],"2":[351.8,68.5,31.6,26.5],"3":[501.3,68.5,28.8,26.5],"4":[651.3,68.5,31.6,26.5]},"B","Конфеты поровну",[["Что означает «поровну»?","Число конфет должно делиться на количество гостей без остатка."],["Проверь варианты","36 = 6 × 6. Значит, гостей могло быть шестеро, и каждый получил бы по 6 конфет."]],""],[834,236,"Прямоугольное зеркало разбилось. Какой кусочек выпал?",{"0":[51.8,91.1,31.6,26.5],"1":[261.6,91.1,31.6,26.5],"2":[478.2,91.1,31.6,26.5],"3":[51.8,202.8,28.8,26.5],"4":[261.6,202.8,31.6,26.5]},"B","Осколок зеркала",[["Найди внешние края","В пустом месте зеркала надо восстановить кусочек нижнего края и кусочек левого края. Они образуют прямой угол."],["Сопоставь контур","От концов этих краёв две наклонные линии сходятся в точке, где сошлись трещины. Так устроен осколок Б."]],""],[855,157,"Когда Буратино врет, его нос удлиняется на 6 см. Когда он говорит правду, его нос становится короче на 2 см. Утром длина его носа была 9 см. За день он три раза соврал и два раза сказал правду. Какой длины стал нос у Буратино к вечеру?",{"0":[51.8,123.2,31.6,26.5],"1":[201.8,123.2,31.6,26.5],"2":[351.8,123.2,31.6,26.5],"3":[501.3,123.2,28.8,26.5],"4":[651.3,123.2,31.6,26.5]},"D","Нос Буратино",[["Посчитай прибавку","Три раза по 6 см дают прибавку 18 см."],["Учти правду","Два раза по 2 см означают, что надо вычесть 4 см. К вечеру длина стала 9 + 18 − 4 = 23 см."]],""],[855,272,"Аня зашла в парк и пошла по аллее в направлении, указанном стрелочкой. На каждом перекрестке она поворачивала направо или налево. Сначала Аня повернула направо, затем налево, потом опять налево, затем направо, потом еще раз направо и дошла до следующего перекрестка. В каком месте оказалась Аня?",{"0":[51.8,234.3,31.6,26.5],"1":[156.1,234.3,31.6,26.5],"2":[261,234.3,31.6,26.5],"3":[365.9,234.3,28.8,26.5],"4":[471.4,234.3,31.6,26.5]},"D","Путь по аллеям",[["Следи за направлением","От входа Аня идёт вверх. После первых трёх поворотов она идёт вправо, вверх и влево."],["Дойди до перекрёстка","Теперь два правых поворота ведут вверх и вправо. Следующий перекрёсток — Г."]],""],[855,129,"В этом году конкурс «Кенгуру» проводится в России в двадцатый раз. Федин папа участвовал в самом первом конкурсе, когда учился в десятом классе. Сколько лет ему может быть сейчас?",{"0":[51.8,95.6,31.6,26.5],"1":[201.8,95.6,31.6,26.5],"2":[351.8,95.6,31.6,26.5],"3":[501.3,95.6,28.8,26.5],"4":[651.3,95.6,31.6,26.5]},"C","Первый конкурс",[["Сколько прошло лет?","От первого конкурса до двадцатого прошло 19 лет."],["Проверь возраст","37 − 19 = 18. В 18 лет можно учиться в десятом классе. У остальных вариантов возраст в год первого конкурса слишком мал или слишком велик."]],""],[855,75,"Сколько чисел между 20 и 30 делятся на свою последнюю цифру?",{"0":[51.8,41.5,31.6,26.5],"1":[201.8,41.5,31.6,26.5],"2":[351.8,41.5,31.6,26.5],"3":[501.3,41.5,28.8,26.5],"4":[651.3,41.5,31.6,26.5]},"C","Деление на последнюю цифру",[["Убери единицы","Число между 20 и 30 состоит из 20 и последней цифры. Последняя цифра делится сама на себя, поэтому достаточно проверить, делится ли на неё 20."],["Посчитай делители","Из цифр от 1 до 9 подходят 1, 2, 4 и 5. Получаются четыре числа: 21, 22, 24 и 25."]],""],[855,129,"22 марта Наташа сказала: «Позавчера оставалась неделя до моего дня рождения». Когда она будет вспоминать, что неделю назад был ее день рождения?",{"0":[51.8,95.6,31.6,26.5],"1":[201.8,95.6,31.6,26.5],"2":[351.8,95.6,31.6,26.5],"3":[501.3,95.6,28.8,26.5],"4":[651.3,95.6,31.6,26.5]},"D","День рождения Наташи",[["Отсчитай до праздника","Позавчера от 22 марта — 20 марта. Ещё семь дней — 27 марта, день рождения Наташи."],["Отсчитай после праздника","До 31 марта остаётся четыре дня, а ещё три приходятся на апрель. Значит, через неделю будет 3 апреля."]],""],[855,156,"Саша хочет закрасить несколько квадратиков на рисунке так, чтобы среди них никакие два не имели общей стороны. Какое наибольшее число квадратиков сможет закрасить Саша?",{"0":[51.8,122.7,31.6,26.5],"1":[201.8,122.7,31.6,26.5],"2":[351.8,122.7,31.6,26.5],"3":[501.3,122.7,28.8,26.5],"4":[651.3,122.7,31.6,26.5]},"B","Квадратики без соседей",[["Ограничь число","В горизонтальном ряду шесть клеток. Разбей их на три соседние пары. В каждой паре можно закрасить максимум одну клетку, а вне ряда есть ещё четыре клетки."],["Построй пример","Закрась все четыре клетки над и под рядом. В ряду можно взять первую, третью и шестую клетки слева. Получится 7."]],""],[855,140,"В марте кот Тоша проспал ровно 2 недели. Сколько часов он бодрствовал в этом месяце?",{"0":[51.8,70.2,31.6,26.5],"1":[311.8,70.2,31.6,26.5],"2":[578,70.2,31.6,26.5],"3":[51.8,105.8,28.8,26.5],"4":[311.8,105.8,31.6,26.5]},"E","Сон кота Тоши",[["Посчитай дни","В марте 31 день, из них кот спал 2 × 7 = 14 дней. Значит, он бодрствовал 31 − 14 = 17 суток."],["Переведи в часы","В сутках 24 часа. Подходит запись (31 − 7 × 2) × 24."]],""],[834,184,"Одноклассники Тони, Бетти, Кэтти и Энди родились в один год. Их дни рождения: 20 февраля, 12 апреля, 12 мая и 25 мая. Дни рождения Бетти и Энди в одном месяце, а дни рождения Энди и Кэтти приходятся на одно число. Кто из детей самый старший?",{"0":[51.8,123.2,31.6,26.5],"1":[201.8,123.2,31.6,26.5],"2":[351.8,123.2,31.6,26.5],"3":[501.3,123.2,28.8,26.5],"4":[51.8,149.7,31.6,26.5]},"A","Кто родился раньше?",[["Найди майские дни","Только в мае есть два дня рождения. Значит, Бетти и Энди родились в мае."],["Определи оставшиеся даты","У Энди тот же номер дня, что у Кэтти, значит, это 12 мая и 12 апреля. Тони родился 20 февраля и старше всех."]],""],[834,156,"В квадратной коробке в два слоя уложены одинаковые квадратные шоколадки. Кирилл съел все 20 шоколадок, которые лежали в верхнем слое вдоль стенок коробки. Сколько шоколадок было в этой коробке сначала?",{"0":[51.8,122.7,31.6,26.5],"1":[201.8,122.7,31.6,26.5],"2":[351.8,122.7,31.6,26.5],"3":[501.3,122.7,28.8,26.5],"4":[651.3,122.7,31.6,26.5]},"D","Шоколадки в два слоя",[["Посчитай стороны","Краевые шоколадки можно разложить на четыре одинаковые группы, по одной на каждую стенку. В каждую группу включи только один угол. Получится 20 : 4 = 5."],["Восстанови коробку","Вдоль каждой стенки 6 шоколадок, если считать оба угла. В двух слоях было 2 × 6 × 6 = 72 шоколадки."]],""],[834,130,"Отцу сейчас 33 года, а его трем сыновьям 5, 6 и 10 лет. Через сколько лет трем сыновьям вместе будет столько же лет, сколько будет отцу?",{"0":[51.8,95.6,31.6,26.5],"1":[201.8,95.6,31.6,26.5],"2":[351.8,95.6,31.6,26.5],"3":[501.3,95.6,28.8,26.5],"4":[651.3,95.6,31.6,26.5]},"B","Отец и сыновья",[["Найди разницу","Сыновьям вместе 5 + 6 + 10 = 21 год, а отцу 33 года. Разница — 12 лет."],["Проследи, как она меняется","За год общий возраст сыновей увеличивается на 3 года, а возраст отца — на 1. Разница уменьшается на 2 года за год и исчезнет через 6 лет."]],""],[834,247,"У Кати есть 6 деталей, изображенных на рисунке. Из пяти деталей она сложила 2 фигуры: прямоугольник, одна из сторон которого равна 6, и квадрат. Какая деталь оказалась лишней?",{"0":[51.8,174,31.6,26.5],"1":[268.4,174,31.6,26.5],"2":[444.9,174,31.6,26.5],"3":[651.3,174,28.8,26.5],"4":[51.8,212.3,31.6,26.5]},"A","Квадрат и прямоугольник",[["Собери квадрат","Две детали по две клетки положи одна над другой. Получится квадрат 2 × 2."],["Собери прямоугольник","Из двух уголков по три клетки можно сложить блок 2 × 3. Приложи к нему блок из шести клеток. Получится прямоугольник 2 × 6, а полоска из четырёх клеток останется."]],""],[834,130,"Мама купила трем своим детям 17 маленьких пирожных. Миша съел в два раза больше пирожных, чем Маша, а Даша съела больше Маши, но меньше Миши. Сколько пирожных съела Даша?",{"0":[51.8,95.6,31.6,26.5],"1":[165.2,95.6,31.6,26.5],"2":[278,95.6,31.6,26.5],"3":[391.3,95.6,28.8,26.5],"4":[501.3,95.6,31.6,26.5]},"B","Семнадцать пирожных",[["Выбери число для Маши","Если Маша съела не больше 3, то Миша съел не больше 6 и Даша — не больше 5. До 17 не хватит. Если Маша съела хотя бы 5, Миша съел не меньше 10, а Даша — хотя бы 6. Это уже больше 17."],["Проверь остаток","Маша съела 4 пирожных, а Миша — 8. Даше осталось 17 − 4 − 8 = 5, что подходит по условию."]],""],[834,124,"Сколько треугольников на рисунке?",{"0":[51.8,79.3,31.6,26.5],"1":[165.2,79.3,31.6,26.5],"2":[278,79.3,31.6,26.5],"3":[391.3,79.3,28.8,26.5],"4":[501.3,79.3,31.6,26.5]},"E","Треугольники на рисунке",[["Считай с горизонтальным основанием","У верхней перекладины 4 треугольника, у средней — 5, а у нижней стороны, включая её половины, — 3."],["Добавь наклонные","У перекрещённых линий есть по одному боковому треугольнику слева и справа. Ещё два треугольника идут от верхней вершины вдоль одной из перекрещённых линий. Всего 4 + 5 + 3 + 2 + 2 = 16."]],""],[834,156,"Из детей, которые пришли в гости к Наде, больше половины были мальчики. Больше трети мальчиков звали Федя. Всего среди гостей было три Феди. Какое наибольшее количество детей могло быть в гостях у Нади?",{"0":[51.8,122.7,31.6,26.5],"1":[201.8,122.7,31.6,26.5],"2":[351.8,122.7,31.6,26.5],"3":[501.3,122.7,28.8,26.5],"4":[651.3,122.7,31.6,26.5]},"D","Гости Нади",[["Ограничь число мальчиков","Три Феди — больше трети мальчиков. При 9 мальчиках 3 было бы ровно третью, значит, мальчиков не больше 8."],["Проверь максимум","Чтобы мальчики были в большинстве, при 8 мальчиках девочек может быть максимум 7. Всего тогда 15 детей."]],""],[855,294,"У Васи есть 7 доминошек, которые изображены на рисунке. Он хочет выложить их в линию, следуя обычным правилам игры в домино (в соседних квадратах двух соседних доминошек должно быть одинаковое количество точек). Какое наибольшее количество доминошек может быть в такой линии?",{"0":[51.8,260.3,31.6,26.5],"1":[201.8,260.3,31.6,26.5],"2":[351.8,260.3,31.6,26.5],"3":[501.3,260.3,28.8,26.5],"4":[651.3,260.3,31.6,26.5]},"C","Цепочка домино",[["Посчитай половинки","У каждого числа от 1 до 6 нечётное число половинок. Внутри цепочки половинки с одинаковыми числами идут парами, поэтому нечётных чисел может быть максимум два — на концах."],["Проверь шесть костяшек","Если убрать одну костяшку, нечётными останутся четыре числа. Значит, из шести и из семи костяшек цепочки нет."],["Построй цепочку","Пять костяшек соединяются так: 6–2, 2–1, 1–3, 3–4, 4–5."]],""],[855,130,"50 мальчиков и 36 девочек встали в круг, держась за руки. Ровно у 26 мальчиков соседка справа — девочка. У скольких мальчиков соседка слева — девочка?",{"0":[53.5,95.6,31.6,26.5],"1":[204.6,95.6,31.6,26.5],"2":[358,95.6,31.6,26.5],"3":[501.3,95.6,28.8,26.5],"4":[651.3,95.6,31.6,26.5]},"D","Соседи в кругу",[["Разбей круг на группы","Иди по кругу в одном направлении. Каждый переход от мальчика к девочке начинает новую группу девочек."],["Сравни переходы","В конце каждой такой группы снова стоит мальчик. Поэтому переходов между мальчиками и девочками в каждую сторону поровну — по 26."]],""],[855,136,"Крошка Ру умеет писать только две цифры: 1 и 7. Он хочет написать несколько чисел, сумма которых равна 2013. Какое наименьшее количество чисел ему придется написать?",{"0":[51.8,102.4,31.6,26.5],"1":[201.8,102.4,31.6,26.5],"2":[351.8,102.4,31.6,26.5],"3":[501.3,102.4,28.8,26.5],"4":[651.3,102.4,31.6,26.5]},"B","Числа из единиц и семёрок",[["Докажи, что двух мало","Число 2013 нельзя записать одними цифрами 1 и 7. Любое разрешённое число нечётное, а сумма двух нечётных чётная."],["Сложи три числа","1771 + 171 + 71 = 2013. Все три числа подходят."]],""],[855,292,"Из большого покрашенного куба Катя вырезала 4 маленьких кубика. Затем она сделала отпечатки всех покрашенных граней новой фигуры. Сколько из следующих пяти картинок у нее получилось?",{"0":[51.8,258,31.6,26.5],"1":[201.8,258,31.6,26.5],"2":[351.8,258,31.6,26.5],"3":[501.3,258,28.8,26.5],"4":[651.3,258,31.6,26.5]},"D","Отпечатки куба",[["Смотри только на наружные грани","Белые стенки выемок не окрашены. Для отпечатка каждой грани начни с квадрата 3 × 3 и убери клетки вырезанных кубиков."],["Сравни видимые грани","На правой грани вырезано три угла. Она даёт второй отпечаток. На левой грани вырезаны два противоположных угла. Она даёт третий отпечаток."],["Проверь другие стороны","На нижней грани вырезаны два угла вдоль одного края. Это первый отпечаток. На одной из задних граней вырезан только один угол. Это четвёртый отпечаток. Для креста понадобилось бы убрать все четыре угла одной грани, а такой грани нет."]],""],[855,163,"Какое наименьшее количество карточек с цифрами (по одной цифре на каждой) надо иметь, чтобы можно было выложить любые четыре различных числа от 1 до 300 одновременно? (Карточки с цифрой 6 можно использовать и для обозначения цифры 9.)",{"0":[51.8,129.4,31.6,26.5],"1":[201.8,129.4,31.6,26.5],"2":[351.8,129.4,31.6,26.5],"3":[501.3,129.4,28.8,26.5],"4":[651.3,129.4,31.6,26.5]},"B","Карточки с цифрами",[["Ищи самые трудные четвёрки","Для каждой цифры выбери четыре числа, в которых она встречается чаще всего. Например, 100, 200, 300 и 10 требуют 7 нулей, а 111 и три числа с двумя единицами требуют 9 единиц."],["Сложи запасы","Для 1 и 2 нужно по 9 карточек. Для 6 и 9 хватит 8 общих, например для 66, 69, 96, 99. Для 0, 3, 4, 5, 7 и 8 нужно по 7. Всего 9 + 9 + 8 + 6 × 7 = 68."]],""]]]];
globalThis.KENGURU_LEGACY_CONDITIONS = {"2013":{"1":{"question":"Какую из букв слова КЕНГА можно написать, не отрывая карандаша от бумаги и не проходя по одной линии дважды?","choices":["К","Е","Н","Г","А"]},"2":{"question":"В равенстве 4●+ 5●= 104 символом ● заменена одна и та же цифра. Какая?","choices":["2","4","5","6","7"]},"3":{"question":"Какая геометрическая фигура отсутствует на этом рисунке?","choices":["круг","треугольник","квадрат","прямоугольник","шестиугольник"],"image":"assets/legacy-conditions/2013/task-03.webp","imageWidth":159,"imageHeight":224},"4":{"question":"Миша измерил длины пяти палочек и записал результаты этих измерений. Какой из результатов А–Д самый большой?","choices":["3 дм 2 см","3 см 7 мм","35 мм","3 см","302 мм"]},"5":{"question":"Пятеро мальчиков обсуждали свойства числа 325. Андрей: «Это трехзначное число». Боря: «Все цифры этого числа различны». Витя: «Сумма его цифр равна 10». Гриша: «Цифра единиц равна 5». Даня: «Все его цифры нечетны». Кто из мальчиков ошибся?","choices":["Андрей","Боря","Витя","Гриша","Даня"]},"6":{"question":"У Пети было 36 конфет. Он раздал все конфеты гостям поровну. Сколько гостей у него могло быть?","choices":["5","6","7","8","10"]},"7":{"question":"Прямоугольное зеркало разбилось. Какой кусочек выпал?","image":"assets/legacy-conditions/2013/task-07.webp","imageWidth":976,"imageHeight":259},"8":{"question":"Когда Буратино врет, его нос удлиняется на 6 см. Когда он говорит правду, его нос становится короче на 2 см. Утром длина его носа была 9 см. За день он три раза соврал и два раза сказал правду. Какой длины стал нос у Буратино к вечеру?","choices":["14 см","15 см","19 см","23 см","31 см"]},"9":{"question":"Аня зашла в парк и пошла по аллее в направлении, указанном стрелочкой. На каждом перекрестке она поворачивала направо или налево. Сначала Аня повернула направо, затем налево, потом опять налево, затем направо, потом еще раз направо и дошла до следующего перекрестка. В каком месте оказалась Аня?","choices":["A","Б","В","Г","Д"],"image":"assets/legacy-conditions/2013/task-09.webp","imageWidth":437,"imageHeight":462},"10":{"question":"В этом году конкурс «Кенгуру» проводится в России в двадцатый раз. Федин папа участвовал в самом первом конкурсе, когда учился в десятом классе. Сколько лет ему может быть сейчас?","choices":["20","27","37","50","55"]},"11":{"question":"Сколько чисел между 20 и 30 делятся на свою последнюю цифру?","choices":["2","3","4","5","6"]},"12":{"question":"22 марта Наташа сказала: «Позавчера оставалась неделя до моего дня рождения». Когда она будет вспоминать, что неделю назад был ее день рождения?","choices":["27 марта","29 марта","2 апреля","3 апреля","5 апреля"]},"13":{"question":"Саша хочет закрасить несколько квадратиков на рисунке так, чтобы среди них никакие два не имели общей стороны. Какое наибольшее число квадратиков сможет закрасить Саша?","choices":["8","7","6","5","4"],"image":"assets/legacy-conditions/2013/task-13.webp","imageWidth":200,"imageHeight":111},"14":{"question":"В марте кот Тоша проспал ровно 2 недели. Сколько часов он бодрствовал в этом месяце?","choices":["(31− 7) ⋅ 2 ⋅ 24","(31 − 7 ⋅ 2) ⋅ 24 ⋅ 60","(30 − 7 ⋅ 2) ⋅ 24","(30 − 7 ⋅ 2) ⋅ 24 ⋅ 60","(31− 7 ⋅ 2) ⋅ 24"]},"15":{"question":"Одноклассники Тони, Бетти, Кэтти и Энди родились в один год. Их дни рождения: 20 февраля, 12 апреля, 12 мая и 25 мая. Дни рождения Бетти и Энди в одном месяце, а дни рождения Энди и Кэтти приходятся на одно число. Кто из детей самый старший?","choices":["Тони","Бетти","Кэтти","Энди","невозможно определить"]},"16":{"question":"В квадратной коробке в два слоя уложены одинаковые квадратные шоколадки. Кирилл съел все 20 шоколадок, которые лежали в верхнем слое вдоль стенок коробки. Сколько шоколадок было в этой коробке сначала?","choices":["50","52","70","72","98"]},"17":{"question":"Отцу сейчас 33 года, а его трем сыновьям 5, 6 и 10 лет. Через сколько лет трем сыновьям вместе будет столько же лет, сколько будет отцу?","choices":["4","6","8","10","12"]},"18":{"question":"У Кати есть 6 деталей, изображенных на рисунке. Из пяти деталей она сложила 2 фигуры: прямоугольник, одна из сторон которого равна 6, и квадрат. Какая деталь оказалась лишней?","image":"assets/legacy-conditions/2013/task-18.webp","imageWidth":965,"imageHeight":300},"19":{"question":"Мама купила трем своим детям 17 маленьких пирожных. Миша съел в два раза больше пирожных, чем Маша, а Даша съела больше Маши, но меньше Миши. Сколько пирожных съела Даша?","choices":["4","5","6","7","8"]},"20":{"question":"Сколько треугольников на рисунке?","choices":["8","9","14","15","16"],"image":"assets/legacy-conditions/2013/task-20.webp","imageWidth":178,"imageHeight":151},"21":{"question":"Из детей, которые пришли в гости к Наде, больше половины были мальчики. Больше трети мальчиков звали Федя. Всего среди гостей было три Феди. Какое наибольшее количество детей могло быть в гостях у Нади?","choices":["12","13","14","15","16"]},"22":{"question":"У Васи есть 7 доминошек, которые изображены на рисунке. Он хочет выложить их в линию, следуя обычным правилам игры в домино (в соседних квадратах двух соседних доминошек должно быть одинаковое количество точек). Какое наибольшее количество доминошек может быть в такой линии?","choices":["3","4","5","6","7"],"image":"assets/legacy-conditions/2013/task-22.webp","imageWidth":857,"imageHeight":67},"23":{"question":"50 мальчиков и 36 девочек встали в круг, держась за руки. Ровно у 26 мальчиков соседка справа — девочка. У скольких мальчиков соседка слева — девочка?","choices":["10","14","24","26","36"]},"24":{"question":"Крошка Ру умеет писать только две цифры: 1 и 7. Он хочет написать несколько чисел, сумма которых равна 2013. Какое наименьшее количество чисел ему придется написать?","choices":["2","3","5","7","9"]},"25":{"question":"Из большого покрашенного куба Катя вырезала 4 маленьких кубика. Затем она сделала отпечатки всех покрашенных граней новой фигуры. Сколько из следующих пяти картинок у нее получилось?","choices":["1","2","3","4","5"],"image":"assets/legacy-conditions/2013/task-25.webp","imageWidth":956,"imageHeight":282},"26":{"question":"Какое наименьшее количество карточек с цифрами (по одной цифре на каждой) надо иметь, чтобы можно было выложить любые четыре различных числа от 1 до 300 одновременно? (Карточки с цифрой 6 можно использовать и для обозначения цифры 9.)","choices":["16","68","74","90","160"]}}};
'use strict';

(() => {
  const latin = ['A', 'B', 'C', 'D', 'E'];
  const cyrillic = ['А', 'Б', 'В', 'Г', 'Д'];
  const escape = value => String(value).replaceAll('&', '&amp;').replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;').replaceAll('"', '&quot;');
  const archive = globalThis.KENGURU_ARCHIVE ??= {};
  const source = 'https://ipokengu.ru/public/task';
  const ink = '#173439';
  const teal = '#237e79';
  const mint = '#e5f2ea';
  const muted = '#e8eee8';
  const line = '#b3c6bf';
  const gold = '#f7dda8';

  const text = (x, y, value, size = 27, color = ink, anchor = 'middle') =>
    `<text x="${x}" y="${y}" fill="${color}" font-family="system-ui, sans-serif" font-weight="700" font-size="${size}" text-anchor="${anchor}" dominant-baseline="middle">${escape(value)}</text>`;
  const box = (x, y, w, h, fill, stroke = 'none', radius = 10) =>
    `<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${radius}" fill="${fill}" stroke="${stroke}"/>`;
  const segment = (x1, y1, x2, y2, color, width = 3) =>
    `<path d="M${x1} ${y1} L${x2} ${y2}" fill="none" stroke="${color}" stroke-width="${width}" stroke-linecap="round"/>`;
  const dot = (x, y, radius, fill) => `<circle cx="${x}" cy="${y}" r="${radius}" fill="${fill}"/>`;
  const svg = (width, height, label, inside, className = 'legacy-scene') =>
    `<svg class="${className}" viewBox="0 0 ${width} ${height}" role="img" aria-label="${escape(label)}">${inside}</svg>`;
  const image = (url, width, height) => `<image href="${url}" width="${width}" height="${height}"/>`;
  const progress = (frame, end) => Math.max(0, Math.min(1, frame / end));

  function renderOriginal(url, width, height, label, mark, frame) {
    let focus = '';
    if (mark) {
      const [x, y, w, h] = mark;
      const dash = .68 + .32 * progress(frame, 8);
      focus = `<rect x="${x - 4}" y="${y - 2}" width="${w + 8}" height="${h + 4}" rx="4" fill="none" stroke="${teal}" stroke-width="4" pathLength="1" stroke-dasharray="${dash} 1"/>`;
    }
    return svg(width, height, label, image(url, width, height) + focus);
  }

  function crop(url, width, height, [sx, sy, sw, sh], x, y, w, h) {
    return `<svg x="${x}" y="${y}" width="${w}" height="${h}" viewBox="${sx} ${sy} ${sw} ${sh}" style="overflow:hidden">${image(url, width, height)}</svg>`;
  }

  function workedScene([height, drawing], label, answer) {
    const size = 720;
    const band = answer ? 51 : 0;
    const badge = answer
      ? box(16, height, size - 32, 42, mint, line) + text(size / 2, height + 21, `Ответ ${answer}`, 24, teal)
      : '';
    return svg(size, height + band, label, drawing + badge, 'legacy-scene legacy-worked-scene');
  }

  // Extract only equations that the author explicitly uses in this step. A
  // space can group thousands, so it must not split their numeric tokens.
  const number = String.raw`[−-]?\d+(?:[ \u00a0\u202f]\d{3}(?!\d))*(?:[.,]\d+)?`;
  const operator = String.raw`[+−–×·⋅*÷:/=<>≤≥-]`;
  const equation = new RegExp(String.raw`${number}(?:\s*${operator}\s*${number})+`, 'gu');
  const tokens = new RegExp(String.raw`^(${number})|(${operator})\s*(${number})`, 'gu');

  function equationsIn(message) {
    return [...message.matchAll(equation)].map(match => match[0])
      .filter(value => /[=<>≤≥]/u.test(value))
      .map(value => [...value.matchAll(tokens)].flatMap(([, first, sign, next]) => first ? [first] : [sign, next]));
  }

  function drawEquations(rows, frame) {
    const drawing = rows.map((parts, row) => {
      const current = Math.min(parts.length - 1, Math.floor(Math.max(0, frame - row * 4) / 2));
      const sizes = parts.map((part, i) => i % 2 ? 32 : Math.max(48, 23 + part.length * 17));
      const width = sizes.reduce((sum, w) => sum + w, 0);
      const factor = Math.min(640 / width, 1);
      let x = (720 - width * factor) / 2;
      const y = 15 + row * 75;
      return box(16, y, 688, 62, '#f6f8f3') + parts.map((part, i) => {
        const w = sizes[i] * factor;
        const highlight = current === i;
        const result = i === parts.length - 1;
        const plate = (i % 2 === 0 || highlight)
          ? box(x + 2, y + 7, w - 4, 48, highlight ? gold : result ? mint : '#fff', result ? teal : 'none') : '';
        const item = plate + text(x + w / 2, y + 31, part, 32 * factor, result ? teal : ink);
        x += w;
        return item;
      }).join('');
    }).join('');
    return [rows.length * 75 + 13, drawing];
  }

  // The checked statement and the worksheet choices are transcribed together.
  // For illustrated choices, the approach below uses the original artwork.
  const authored = {
    '2001/3': {
      question: 'У Йозефа было 7 палочек. Он разломал одну из них пополам. Сколько теперь у него палочек?',
      choices: ['5', '6', '7', '8', '9'],
      draw: drawSticks,
    },
    '2002/2': {
      question: 'Чему равно число 2 + 2 − 2 + 2 − 2 + 2 − 2 + 2 − 2 + 2?',
      choices: ['0', '2', '4', '12', '20'],
      draw: drawPairs,
    },
    '2003/3': {
      question: 'На какой картинке сердечки составляют ровно три четверти от общего числа фигурок?',
      crop: [73, 65, 662, 131],
      illustration: 'Пять рисунков с сердечками, ромбами и треугольниками, варианты от A до E',
      draw: drawHearts,
    },
    '2004/4': {
      question: 'Сережа шел по лестнице, шагая через ступеньку (первую ступеньку он пропустил). При этом он считал шаги: «Один, два, три…». После того, как он сказал «пять», оказалось, что осталась одна ступенька. Сколько всего ступенек на лестнице?',
      choices: ['5', '7', '9', '11', '12'],
      draw: drawStairs,
    },
    '2005/3': {
      question: 'Каждый из восьми кенгуру может перепрыгнуть на любую клетку квадратной таблицы 4 × 4. Им надо расположиться так, чтобы в каждой строчке и каждом столбце этой таблицы оказалось ровно по 2 кенгуру. Какое наименьшее число кенгуру должно для этого прыгнуть?',
      choices: ['4', '3', '2', '1', '0'],
      crop: [537, 8, 244, 240],
      illustration: 'Квадратная таблица с восемью кенгуру',
      draw: drawKangaroos,
    },
    '2006/10': {
      question: 'Петя прибавляет различные однозначные числа к числу 96. Сколько раз он получит трехзначное число?',
      choices: ['3', '4', '5', '6', '7'],
      draw: drawNumberLine,
    },
    '2007/1': {
      question: 'Сколько общих букв у слов КЕНГУРУ и МАТЕМАТИКА?',
      choices: ['1', '2', '3', '4', '5'],
      draw: drawLetters,
    },
    '2008/6': {
      question: 'В первом аквариуме на 12 рыбок больше, чем во втором. Сколько рыбок надо переселить из первого аквариума во второй, чтобы рыбок в них стало поровну?',
      choices: ['12', '8', '6', '4', '2'],
      draw: drawAquariums,
    },
    '2009/2': {
      question: '200 × 9 + 200 + 9 = ?',
      choices: ['418', '1909', '2009', '4018', '20009'],
    },
    '2010/2': {
      question: 'Дети измерили шагами длину дорожки. У Ани получилось 17 шагов, у Наташи 15, у Дениса 14, у Вани 13 и у Тани 12. Кто из этих детей имеет самый длинный шаг?',
      choices: ['Аня', 'Наташа', 'Денис', 'Ваня', 'Таня'],
      draw: (step, frame) => drawBars(
        ['Аня', 'Наташа', 'Денис', 'Ваня', 'Таня'], [17, 15, 14, 13, 12], step === 2 ? 4 : -1, frame),
    },
    '2011/3': {
      question: 'Через три с половиной часа отправляется поезд, на котором Сёма поедет к бабушке. Боясь проспать, он проснулся полтора часа назад. За сколько часов до отправления поезда Сёма проснулся?',
      choices: ['за полтора часа', 'за 2 часа', 'за 3 с половиной часа', 'за 4 часа', 'за 5 часов'],
      draw: (step, frame) => drawTimeline(
        ['Пробуждение', 'Сейчас', 'Отправление'], [1.5, 3.5], ['1,5 ч', '3,5 ч'], step === 2 ? '5 часов' : '', frame),
    },
    '2012/4': {
      question: 'Три воздушных шарика стоят на 12 рублей больше, чем один шарик. Сколько стоит один шарик?',
      choices: ['4 руб.', '6 руб.', '8 руб.', '10 руб.', '12 руб.'],
      draw: drawBalloons,
    },
    '2013/4': {
      question: 'Миша измерил длины пяти палочек и записал результаты этих измерений. Какой из результатов А–Д самый большой?',
      choices: ['3 дм 2 см', '3 см 7 мм', '35 мм', '3 см', '302 мм'],
      draw: (step, frame) => step === 1
        ? drawEquations(equationsIn('300 + 20 = 320'), frame)
        : drawBars(['А', 'Б', 'В', 'Г', 'Д'], [320, 37, 35, 30, 302], 0, frame, ' мм'),
    },
    '2014/1': {
      question: 'Боря выложил из одинаковых палочек слово КЕНГУРУ. Сколько букв сложены из 5 палочек?',
      choices: ['2', '3', '4', '5', '6'],
      crop: [447, 4, 348, 81],
      illustration: 'Буквы слова КЕНГУРУ, сложенные из палочек',
      draw: drawStickLetters,
    },
    '2015/2': {
      question: 'Чему равна сумма двадцати сотен и пятнадцати?',
      choices: ['35', '215', '2015', '20015', '200015'],
    },
    '2016/2': {
      question: 'Крошке Ру 17 марта исполняется 7 недель и 3 дня. Когда ему исполнится 9 недель?',
      choices: ['21 марта', '24 марта', '26 марта', '28 марта', '30 марта'],
      draw: (step, frame) => drawTimeline(
        ['17 марта', step === 2 ? '21 марта' : '8 недель', step === 2 ? '28 марта' : '9 недель'],
        [4, 7], ['4 дня', '7 дней'], step === 2 ? '11 дней' : '', frame),
    },
    '2017/1': {
      question: 'Кенга составила пять примеров на сложение. Какая сумма самая большая?',
      choices: ['2 + 0 + 1 + 7', '2 + 0 + 17', '20 + 17', '20 + 1 + 7', '201 + 7'],
      draw: drawSums,
    },
    '2018/3': {
      question: 'В Петербурге 15 марта в 16 часов пошел снег, а 16 марта в 15 часов снегопад закончился. Сколько часов он продолжался?',
      choices: ['11', '12', '23', '24', '25'],
      draw: (step, frame) => drawTimeline(
        step === 1 ? ['15 марта, 16:00', 'Полночь'] : ['15 марта, 16:00', 'Полночь', '16 марта, 15:00'],
        step === 1 ? [8] : [8, 15], step === 1 ? ['8 ч'] : ['8 ч', '15 ч'], step === 2 ? '23 часа' : '', frame, 23),
    },
    '2019/1': {
      question: 'В зоопарке 21 ноября 2018 года родился кенгуренок. Сколько месяцев ему исполнилось 21 марта 2019 года?',
      choices: ['3', '4', '5', '6', '7'],
      draw: (step, frame) => drawTimeline(
        step === 1 ? ['21 нояб.', '21 дек.', '21 янв.'] : ['21 нояб.', '21 дек.', '21 янв.', '21 февр.', '21 марта'],
        step === 1 ? [1, 1] : [1, 1, 1, 1], step === 1 ? ['1 мес.', '1 мес.'] : ['1 мес.', '1 мес.', '1 мес.', '1 мес.'],
        step === 2 ? '4 месяца' : '', frame, 4),
    },
  };

  function drawSticks(step, frame) {
    let drawing = '';
    for (let i = 0; i < 6; i++) drawing += segment(101 + i * 70, 38, 101 + i * 70, 117, teal, 11);
    drawing += text(275, 150, '6 целых', 26);
    const gap = step === 1 ? 0 : 20 + 9 * progress(frame, 8);
    drawing += segment(567 - gap, 38, 567 - gap, 74, '#bc6340', 11);
    drawing += segment(567 + gap, 82, 567 + gap, 117, '#bc6340', 11);
    drawing += text(567, 150, step === 1 ? 'сломанная' : '2 половины', 26);
    return [180, drawing];
  }

  function drawPairs(step, frame) {
    let drawing = box(17, 22, 119, 61, mint) + text(77, 52, '2 + 2', 30);
    const active = Math.min(3, Math.floor(Math.max(0, frame) / 4));
    for (let i = 0; i < 4; i++) {
      const x = 151 + 139 * i;
      drawing += box(x, 22, 130, 61, step === 1 && i === active ? gold : muted);
      drawing += text(x + 65, 52, step === 1 ? '−2 + 2' : '0', 30);
      if (step === 1) drawing += segment(x + 65, 89, x + 65, 111, teal) + text(x + 65, 137, '0', 26, teal);
    }
    if (step === 2) drawing += text(360, 137, '2 + 2 = 4', 33, teal);
    return [173, drawing];
  }

  function drawHearts(step, frame, card) {
    if (step === 1) {
      let drawing = '';
      for (let i = 0; i < 4; i++) {
        const x = 105 + i * 128;
        drawing += box(x, 40, 105, 81, i === 3 ? muted : mint, line);
        drawing += text(x + 52, 80, i === 3 ? '◇' : '♥', 49, i === 3 ? ink : '#a34849');
      }
      return [175, drawing + text(360, 145, '3 из 4', 30, teal)];
    }
    const [url, w, h] = card;
    const choiceImage = globalThis.KENGURU_CHOICE_LAYOUTS?.['2003-3-4/3']?.options[3]?.image;
    const drawing = choiceImage
      ? `<image href="${escape(choiceImage)}" x="251" y="11" width="228" height="240"/>`
      : crop(url, w, h, [493, 66, 76, 80], 251, 11, 228, 240);
    const alpha = .45 + progress(frame, 9) * .55;
    return [260, drawing +
      `<g opacity="${alpha}">` +
      box(256, 15, 216, 158, 'none', '#a34849') + box(256, 176, 216, 73, 'none', teal) +
      text(490, 94, '9 сердец', 27, '#a34849', 'start') +
      text(490, 206, '3 другие фигуры', 23, teal, 'start') + '</g>'];
  }

  function drawStairs(step, frame) {
    let drawing = '';
    for (let i = 1; i <= 11; i++) {
      const x = 26 + 60 * (i - 1);
      const y = 176 - 13 * (i - 1);
      const landed = i % 2 === 0;
      const active = landed && i / 2 === Math.min(5, 1 + Math.floor(Math.max(frame, 0) / 4));
      const remaining = i === 11 && step === 2;
      drawing += box(x, y, 59, 36, active ? gold : remaining || landed ? mint : muted, line, 4);
      if (i < 11 || remaining) drawing += text(x + 30, y + 18, i, 24, landed || remaining ? teal : ink);
      if (landed) drawing += dot(x + 30, y - 15, active ? 8 : 5, teal);
      if (remaining) drawing += text(x + 30, y - 20, '+1', 22, teal);
    }
    return [225, drawing];
  }

  function drawKangaroos(step, frame, card) {
    const [url, w, h] = card;
    const locations = [[0, 0], [0, 1], [1, 0], [1, 3], [2, 2], [2, 3], [3, 2], [1, 2]];
    let drawing = '';
    for (let row = 0; row < 4; row++) {
      for (let col = 0; col < 4; col++) {
        const fill = step === 1 && (row === 1 || col === 2) ? gold
          : row === 3 && col === 1 ? mint : '#fff';
        drawing += box(204 + col * 64, 14 + row * 64, 64, 64, fill, line, 0);
      }
    }
    const moving = step === 2 ? (frame === 0 ? 1 : progress(frame, 10)) : 0;
    if (step === 2 && frame > 0) {
      drawing += `<path d="M364 110 Q230 144 300 238" fill="none" stroke="${teal}" stroke-width="3" stroke-dasharray="7 5"/>`;
    }
    locations.forEach(([row, col], i) => {
      const active = i === locations.length - 1;
      const shift = active ? moving : 0;
      const x = 210 + col * 64 - shift * 64;
      const y = 21 + row * 64 + shift * 128 - 37 * Math.sin(shift * Math.PI);
      if (active) drawing += box(x - 3, y - 3, 58, 57, mint, teal, 7);
      drawing += `<svg x="${x}" y="${y}" width="52" height="50" viewBox="549 19 49 46" style="overflow:hidden;mix-blend-mode:multiply">${image(url, w, h)}</svg>`;
    });
    const counts = moving === 1 ? [2, 2, 2, 2] : moving === 0 ? [2, 3, 2, 1] : [2, 2, 2, 1];
    for (let i = 0; i < 4; i++) {
      drawing += text(489, 46 + i * 64, counts[i], 24, teal);
      drawing += text(236 + i * 64, 296, i === 1 ? counts[3] : i === 2 ? counts[1] : 2, 24, teal);
    }
    return [321, drawing];
  }

  function drawNumberLine(step, frame) {
    let drawing = segment(44, 99, 676, 99, line, 4);
    for (let i = 0; i < 10; i++) {
      const x = 45 + i * 70;
      const marked = i === 4 || (step === 2 && i > 4);
      const active = i === 4 + Math.min(step === 1 ? 0 : 5, Math.floor(Math.max(0, frame) / 3));
      if (marked) drawing += box(x - 28, 53, 56, 44, active ? gold : mint);
      drawing += text(x, 75, 96 + i, 23, marked ? teal : ink) + dot(x, 99, marked ? 6 : 4, marked ? teal : line);
      if (marked) drawing += text(x, 126, '+' + i, 20, teal);
    }
    return [155, drawing];
  }

  function drawLetters(step, frame) {
    const words = ['КЕНГУРУ', 'МАТЕМАТИКА'];
    const active = Math.min(words[0].length - 1, Math.floor(Math.max(0, frame) / 3));
    return [166, words.map((word, row) => [...word].map((letter, i) => {
      const x = 360 - word.length * 32 + i * 64;
      const y = 19 + row * 67;
      const common = step === 2 && 'КЕ'.includes(letter);
      const comparable = step === 1 && (row === 0 ? i === active : letter === words[0][active]);
      return box(x, y, 56, 54, common ? mint : comparable ? gold : muted, common ? teal : line) +
        text(x + 28, y + 27, letter, 30, common ? teal : ink);
    }).join('')).join('')];
  }

  function drawAquariums(step, frame) {
    const moved = step === 1 ? 1 : 6;
    const now = frame === 0 ? moved : Math.min(moved, 1 + Math.floor(frame / 3));
    let drawing = '';
    for (let tank = 0; tank < 2; tank++) {
      const x = 21 + tank * 365;
      drawing += box(x, 18, 313, 128, mint, line);
      drawing += text(x + 156, 40, tank ? 'Второй аквариум' : 'Первый аквариум', 22);
      drawing += text(x + 40, 96, '□ +', 25, teal);
      for (let i = 0; i < (tank ? now : 12 - now); i++) {
        drawing += dot(x + 81 + (i % 6) * 36, 81 + Math.floor(i / 6) * 33, 11, tank ? '#bc6340' : teal);
      }
    }
    drawing += text(360, 82, '→', 27, ink);
    const difference = now === 6 ? '6 = 6' : `${12 - now} − ${now} = ${12 - 2 * now}`;
    drawing += text(360, 174, difference, 29, teal);
    return [197, drawing];
  }

  function drawBars(names, values, highlighted, frame, unit = '') {
    const max = Math.max(...values);
    const active = Math.min(values.length - 1, Math.floor(Math.max(0, frame) / 3));
    let drawing = '';
    for (let i = 0; i < values.length; i++) {
      const y = 12 + i * 46;
      const w = values[i] / max * 450;
      drawing += text(124, y + 17, names[i], 22, ink, 'end');
      drawing += box(146, y, w, 34, i === highlighted ? teal : i === active ? gold : muted, line, 7);
      drawing += text(156 + w, y + 17, values[i] + unit, 22, i === highlighted ? teal : ink, 'start');
    }
    return [values.length * 46 + 6, drawing];
  }

  function drawTimeline(labels, sizes, durations, total, frame, span = sizes.reduce((sum, size) => sum + size, 0)) {
    const active = Math.min(sizes.length - 1, Math.floor(Math.max(0, frame) / 6));
    let x = 103;
    let drawing = '';
    sizes.forEach((size, i) => {
      const end = x + 514 * size / span;
      drawing += segment(x, 65, end, 65, i === active ? '#c07848' : teal, 8);
      drawing += dot(x, 65, 8, teal);
      drawing += text(x, 100, labels[i], 21);
      drawing += text((x + end) / 2, 34, durations[i], 25, teal);
      x = end;
    });
    drawing += dot(x, 65, 8, teal) + text(x, 100, labels.at(-1), 21);
    if (total) drawing += box(103, 129, 514, 40, mint) + text(360, 149, total, 26, teal);
    return [total ? 183 : 128, drawing];
  }

  function drawBalloons(step, frame) {
    const active = Math.min(2, 1 + Math.floor(Math.max(0, frame) / 4));
    let drawing = segment(343, 62, 586, 62, teal, 3) + text(464, 36, '12 руб.', 26, teal);
    for (let i = 0; i < 3; i++) {
      const x = 175 + i * 144;
      const color = i === 0 ? '#a9b9b2' : i === active ? '#bc6340' : teal;
      drawing += dot(x, 118, 38, color);
      drawing += box(x - 6, 151, 12, 12, color, 'none', 0);
      drawing += segment(x, 162, x, 181, color);
      drawing += text(x, 207, i === 0 ? 'вычитаем' : step === 1 ? '?' : '6 руб.', 25, color);
      if (i === 0) drawing += segment(x - 45, 165, x + 45, 77, '#7d4940', 4);
    }
    return [239, drawing];
  }

  function drawStickLetters(step, frame, card) {
    const [url, w, h] = card;
    const sources = [[449, 42], [492, 48], [541, 53], [597, 49], [645, 46], [692, 52], [745, 48]];
    const values = [4, 5, 5, 3, 3, 5, 3];
    const active = Math.min(6, Math.floor(Math.max(0, frame) / 3));
    let drawing = '';
    for (let i = 0; i < sources.length; i++) {
      const [sx, sw] = sources[i];
      const x = 24 + i * 98;
      const relevant = step === 2 ? values[i] === 5 : values[i] !== 5;
      drawing += box(x, 21, 85, 126, relevant ? mint : muted, relevant ? teal : line);
      drawing += crop(url, w, h, [sx, 8, sw, 75], x + 14, 30, 56, 77);
      if (relevant) drawing += text(x + 43, 125, values[i], 24, active === i ? '#a24d36' : teal);
    }
    return [167, drawing];
  }

  function drawSums(step, frame) {
    if (step === 2) return drawBars(['А', 'Б', 'В', 'Г', 'Д'], [10, 19, 37, 28, 208], 4, frame);
    const expressions = authored['2017/1'].choices;
    const drawing = expressions.map((value, i) => {
      const x = 12 + i * 140;
      return box(x, 25, 135, 61, i === 4 ? mint : muted, i === 4 ? teal : line) +
        text(x + 67, 55, value, 22, i === 4 ? teal : ink);
    }).join('');
    return [113, drawing];
  }

  for (const [year, label, tasks] of globalThis.KENGURU_LEGACY ?? []) {
    const letters = year < 2008 ? latin : cyrillic;
    const lessons = [];
    const scenes = [];
    for (const [i, [width, height, , marks, key, name, explanation, note]] of tasks.entries()) {
      const number = i + 1;
      const answer = key === '?' ? null : latin.indexOf(key);
      const originalImage = `assets/years/${year}/task-${String(number).padStart(2, '0')}.webp`;
      const card = [originalImage, width, height];
      const authoredTask = authored[year + '/' + number];
      const imported = globalThis.KENGURU_LEGACY_CONDITIONS?.[year]?.[number];
      const native = authoredTask ?? imported;
      const illustration = !authoredTask && imported?.image
        ? svg(imported.imageWidth, imported.imageHeight, 'Рисунки и варианты из условия',
            `<image href="${escape(imported.image)}" width="${imported.imageWidth}" height="${imported.imageHeight}"/>`)
          .replace('<svg ', `<svg style="max-width:${imported.imageWidth}px" `)
        : '';
      const steps = [
        ['Твоё решение', 'Условие задачи', 'Выбери свой вариант ответа.'],
        ...explanation.map(([heading, message], stage) => [
          stage === explanation.length - 1 ? 'Ответ' : 'Шаг ' + (stage + 1), heading, message,
        ]),
      ];
      const formulas = explanation.map(([, message]) => equationsIn(message));
      const choice = answer === null ? '' : letters[answer];
      const description = `Условие и варианты задачи ${number} из оригинала.`;
      lessons.push({
        number,
        title: name,
        short: name,
        skill: '',
        answer,
        choices: native?.choices ?? ['', '', '', '', ''],
        choiceImages: native?.choiceImages,
        question: native?.question ?? '',
        conditionImage: !authoredTask ? imported?.image : undefined,
        questionNote: note,
        legacyOriginal: true,
        hideIntroText: Boolean(native),
        showCompletedStep: true,
        points: i < 10 ? 3 : i < 20 ? 4 : 5,
        originalImage,
        steps,
      });
      scenes.push((step, frame) => {
        if (step === 0 && authoredTask) {
          if (!authoredTask.crop) return '';
          const region = authoredTask.crop;
          const cropHeight = Math.round(720 * region[3] / Math.max(600, region[2]));
          const cropWidth = cropHeight * region[2] / region[3];
          return svg(720, cropHeight, authoredTask.illustration,
            crop(...card, region, (720 - cropWidth) / 2, 0, cropWidth, cropHeight));
        }
        if (step === 0 && native) return illustration;
        const final = step === steps.length - 1;
        const revealed = final ? choice : '';
        const answerLabel = revealed ? ` Ответ ${revealed}.` : '';
        if (step > 0) {
          const content = authoredTask?.draw
            ? authoredTask.draw(step, frame * 3, card)
            : formulas[step - 1].length ? drawEquations(formulas[step - 1], frame * 5) : null;
          if (content) return workedScene(content, steps[step][1] + '. ' + steps[step][2] + answerLabel, revealed);
          if (native) {
            if (!revealed) return '';
            return workedScene([0, ''], description + answerLabel, revealed);
          }
        }
        return renderOriginal(...card, description + answerLabel, final ? marks[answer] : null, frame);
      });
    }

    archive[year] = {
      year,
      id: year + '-3-4',
      grades: [3, 4],
      label,
      answerLetters: letters,
      sources: {
        tasksUrl: `${source}/kenguru_${year}_class_3-4.pdf`,
        answersUrl: `${source}/kenguru_${year}_answers.pdf`,
        solutionUrl: null,
      },
      lessons,
      scenes,
    };
  }
})();

